import csv, json
from pathlib import Path
ROOT = Path.cwd(); OUT = ROOT / "02_Research/Subtasks/11_slide3a_research/outputs"
S = json.loads((OUT / "A_q1_vu_summary.json").read_text())
pk_m, pk_v = S["vu_peak_2021_23"]; lt_m, lt_v = S["vu_latest"]; ur_m, ur_v = S["unrate_latest"]
q = S["quarterly_vu"]
