      value_2021_23=f"Current vintage: 2021-23 low {S['unrate_min_2021_23'][1]}% ({S['unrate_min_2021_23'][0]}); {S['unrate_at_vu_peak']}% at the V/U peak month ({pk_m})",
      now_measure_proxy="UNRATE (FRED; BLS LNS14000000), monthly SA",
